// BetterDesktop.Shell.Desktop — 新建菜单文件模板（2026-09-07）
// 「新建 ▸」各格式的最小合法内容：文本类用 UTF-8 直写，二进制/OOXML 用 Base64 内嵌。
// OOXML 模板为最小合法包（Content_Types + rels + document/workbook/presentation），
// Office 可直接打开；zip 为空压缩包（22B EOCD）；bmp 为 1x1 24bit。
// 新增格式：在下方加常量 + DesktopIconsControl 新建子菜单加一项即可。

using System;
using System.Text;

namespace BetterDesktop.Shell.Desktop.Services;

/// <summary>「新建」菜单各格式的最小文件模板（创建时传入 DesktopBrowser.CreateFile）。</summary>
internal static class NewFileTemplates
{
    // ===== 文本类（UTF-8 直写） =====
    public static readonly byte[] Text = Array.Empty<byte>();
    public static readonly byte[] Markdown = Array.Empty<byte>();
    public static readonly byte[] Json = Encoding.UTF8.GetBytes("{}");
    public static readonly byte[] Xml = Encoding.UTF8.GetBytes("<?xml version=\"1.0\" encoding=\"utf-8\"?>");
    public static readonly byte[] Html = Encoding.UTF8.GetBytes("<!DOCTYPE html><html><head><meta charset=\"utf-8\"><title>新建文档</title></head><body></body></html>");
    public static readonly byte[] Csv = Array.Empty<byte>();
    public static readonly byte[] Bat = Encoding.UTF8.GetBytes("@echo off");
    public static readonly byte[] Ps1 = Array.Empty<byte>();
    public static readonly byte[] Py = Array.Empty<byte>();

    // ===== 二进制模板（Base64） =====
    public static readonly byte[] Zip = System.Convert.FromBase64String("UEsFBgAAAAAAAAAAAAAAAAAAAAAAAA==");
    public static readonly byte[] Bmp = System.Convert.FromBase64String("Qk06AAAAAAAAADYAAAAoAAAAAQAAAAEAAAABABgAAAAAAAQAAAAAAAAAAAAAAAAAAAAAAP///wAA");

    // ===== Office 最小合法包（Base64） =====
    public static readonly byte[] Docx = System.Convert.FromBase64String("");
    public static readonly byte[] Xlsx = System.Convert.FromBase64String("");
    public static readonly byte[] Pptx = System.Convert.FromBase64String("");
}
